var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"About Me","text":"Quick access <p>Icon links to my platforms are available at the bottom of this page.      </p>"},{"location":"index.html#profile","title":"Profile","text":"<p>Jeonghun Lee (\uc815\ud6c8 \uc774) (also known as Jeonghun (James) Lee) </p> <p> JeonghunLee Github Profile </p> <p> Jeonghun (James) Lee </p> <p>\u2192 Go To Technical Skills </p> Contact with me <p>The LinkedIn icon links is available at the bottom of this page.  </p> <p></p>"},{"location":"index.html#interests","title":"Interests","text":"<p>I am especially interested in Embedded Firmware, BSP (Linux, RTOS), and DSP systems,   with a strong focus on system-level integration and debugging.   </p> <p>I tend to focus on solving integration-level problems between hardware, firmware, and software,    where timing, reliability, and cross-domain interactions are critical. </p> <p></p>"},{"location":"index.html#technical-blogs","title":"Technical Blogs","text":"<ul> <li>Primary Technical Blog (Blogger) https://ahyuo79.blogspot.com </li> </ul> <p>My main technical portfolio, documenting system-level embedded engineering  thhrough real-world implementation and in-depth   analysis, including:       </p> Primary Technical Blog <p>This blog documents system-level investigations across HW, FW, OS, and DSP,  focusing on debugging processes, design trade-offs, and real-world constraints.  </p> Language and Tags support <p>The blog is primarily written in Korean, with English support available via Google Translate.   All links redirect to my technical blog (Blogger), organized using tag-based categories </p> <p></p> <ul> <li>Secondary Technical Blog (Medium) https://medium.com/@ahyuo79 </li> </ul> Secondary Technical Blog <p>Selected topics from primary technical blog are refined and expanded for a broader, international audience.   </p> <p></p>"},{"location":"index.html#communities","title":"Communities","text":"<ul> <li>\ud83c\udf0d Communities  Actively participating in global semiconductor &amp; embedded engineering communities    (using my private email / private ID(ahyuo79)):   <ul> <li>NXP Community </li> <li>NVIDIA Developer Forums </li> <li>TI E2E Forum </li> </ul> </li> </ul> Community Preference <p>I value engineering cultures that focus on open technical discussion,   documentation, and reference designs as core parts of the development process.      I also take part in various engineering communities and local meetups to exchange ideas and learn from different perspectives  </p> <p></p>"},{"location":"project_ai.html","title":"AI","text":"Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.     </p>"},{"location":"project_ai.html#technical-blog","title":"Technical Blog","text":"<ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Information Tags AI AI-Tensorflow /  AI-Machine Deep Learning / AI-TinyML How to use these links <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.</p> <p>Go Back Technical-Skills-&gt;AI and Edge AI </p> <p></p>"},{"location":"project_ai.html#ai-agent-with-mcp","title":"AI-Agent with MCP","text":"<ul> <li> <p>Purpose </p> <ul> <li>AI Agent workflow based on MCP   </li> <li>Connect Claude, Codex, Ollama, and GitHub operations through MCP   </li> <li>Support MCP-based local execution </li> <li>Support Devops CI/CD/CT automation <ul> <li>Github-based CI/CD/CT: GitHub Actions with Github Issue, Self-hosted runners. </li> <li>Jenkins-based CI/CD/CT: automation within a documentation-first project workflow. </li> </ul> </li> </ul> </li> <li> <p>Links</p> <ul> <li> GIT: https://github.com/JeonghunLee/local-ai-agent-mcp</li> <li>Supported Documentation: <ul> <li>GithubPages Hosting only    </li> <li>Go To Documentation-&gt;GithubPages-Project </li> </ul> </li> </ul> </li> <li> <p>Scope</p> <ul> <li>AI Agent usage</li> <li>MCP Tool integration</li> <li>GitHub automation</li> <li>Local TEST execution</li> <li>CI/CD/CT workflow</li> </ul> </li> </ul> <p></p> <p>Technical Summary</p> <ul> <li>AI-based CI/CD/CT automation for code generation, review, testing, and deployment..</li> </ul> <p></p>"},{"location":"project_ai.html#ai-driven-embedded-continuous-testing","title":"AI-driven Embedded Continuous Testing","text":"<ul> <li>Purpose<ul> <li>AI-driven Continuous Testing workflow for embedded systems</li> <li>Support pytest-based CT and unittest-based Unit Test</li> <li>Support Mock / HIL test environments</li> <li>Support hardware test automation with TEST Interface and Equipment separation</li> <li>Support Local LLM Test Review using Ollama</li> <li>Support VS Code Testing / Run and Debug</li> <li>Generate TEST execution history and reports using Markdown</li> <li>Support documentation and document conversion using MkDocs / Pandoc</li> </ul> </li> </ul> <ul> <li> <p>Links</p> <ul> <li> GIT: https://github.com/JeonghunLee/AI-driven-CI-CT</li> <li>Supported Documentation:<ul> <li>GithubPages Hosting only</li> <li>AI-driven Continuous Testing Documentation</li> </ul> </li> <li>TEST Results<ul> <li>Pytest TEST Results</li> <li>Unittest TEST Results</li> </ul> </li> </ul> </li> <li> <p>Scope</p> <ul> <li>Embedded Continuous Testing</li> <li>Pytest TEST Case / TEST ID management</li> <li>Unittest function-based testing</li> <li>Fixture-based Mock / HIL environment</li> <li>TEST Interface / Equipment automation</li> <li>VS Code Testing Adapter / Discovery</li> <li>Local LLM Test Analysis and Review</li> <li>Execution ID / TEST Result history</li> <li>MkDocs / Pandoc TEST documentation</li> </ul> </li> </ul> <p></p> <p>Technical Summary</p> <ul> <li>AI-driven Embedded Continuous Testing using pytest, unittest, Mock/HIL, hardware test automation, VS Code Testing, Ollama, MkDocs, and Pandoc.</li> </ul> <p></p>"},{"location":"project_blogs_management.html","title":"Blog Management","text":"Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.     </p>"},{"location":"project_blogs_management.html#technical-blog","title":"Technical Blog","text":"<ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Information Tags Blog Platform Google-Blogspot How to use these links <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.    </p> <p></p> <ul> <li>Goal  Manage my Technical blogs on Blogger(Korean) and Medium(English).    with lightweight customization using HTML/CSS (and limited JavaScript where available).   </li> </ul> <p></p>"},{"location":"project_blogs_management.html#medium-english","title":"Medium (English)","text":"<ul> <li>Purpose  Rewrite English Medium articles based on existing technical posts from my Blogger(Korean)   </li> </ul> <p>STEP 1 \u2014 Source Select an article from my technical blog (Blogger).  1<sup>st</sup> Blog: https://ahyuo79.blogspot.com </p> <p></p> <p>STEP 2 \u2014 Draft &amp; Backup Translate and refine the content using ChatGPT, then store drafts and backups on GitHub.  GIT: https://github.com/JeonghunLee/Medium  GIT: https://github.com/JeonghunLee/medium-preview </p> <p>Backup Blogger and new HTML based on Markdown</p> <p></p> <p>STEP 3 \u2014 Preview Preview the draft via GitHub Pages before publication.  WEB: https://jeonghunlee.github.io/medium-preview/ </p> <p>GitHub Pages Hosting (Preview Only)</p> <p></p> <p>STEP 4 \u2014 Publish Finalize the article with additional context and publish it on Medium.     2<sup>nd</sup> Blog: https://medium.com/@ahyuo79 </p> <p>Medium Blog (Publish and Test)</p> <p> </p>"},{"location":"project_blogs_management.html#blogger-blogspot","title":"Blogger (Blogspot)","text":"<ul> <li>Purpose  Modularize and maintain JavaScript and CSS assets to optimize the Blogspot UI    while ensuring long-term maintainability and reusability.   with Blogspot Layout     </li> </ul> <ul> <li>Javas Script and CSS (Module) <ul> <li> GIT: https://github.com/JeonghunLee/blogspot </li> <li>Release: https://github.com/JeonghunLee/blogspot/tree/gh-pages </li> </ul> </li> </ul> Github Page Hosting for only JS/CSS Not HTML <p>in deteil README Manaul </p> <p> </p>"},{"location":"project_documentation.html","title":"Documentation","text":"Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.     </p>"},{"location":"project_documentation.html#technical-blog","title":"Technical Blog","text":"<ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Information Tags DevOps \u2013 CI/CD / Docker DevOps-CI/CD / DevOps-Docker DevOps-Docs DevOps-Sphinx / DevOps-MkDocs / DevOps-ReadTheDocs <p>How to use these links</p> <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.</p> <p>Go Back Technical-Skills-&gt;Technical Blog-DevOps </p> <p></p>"},{"location":"project_documentation.html#readthedocs-projects","title":"ReadTheDocs-Projects","text":"<ul> <li>Go Back WIFI Sniffer Project <ul> <li> DOC: https://wifisniffer.readthedocs.io/ko/latest/ </li> <li> CFG: https://app.readthedocs.org/projects/wifisniffer/ </li> </ul> </li> </ul> <p>ReadTheDocs Hosting for Document</p> <p>ReadTheDocs sometimes not working properly (Server Problem)</p> <p></p> <p> View ReadTheDocs Dashboard </p> <p></p>"},{"location":"project_documentation.html#readthedocs-test","title":"ReadTheDocs TEST","text":"<p>ReadTheDocs TEST Hosting Site and Repository</p> <p></p> <ul> <li>ReadTheDoc test00<ul> <li> WEB: https://readthedoc-test00.readthedocs.io/en/latest/ </li> <li> GIT: https://github.com/JeonghunLee/readthedocs.org </li> </ul> </li> </ul> <p></p> <ul> <li>ReadTheDoc Template TEST       <ul> <li> WEB: https://jeonghunlee-demo.readthedocs.io/en/latest/</li> </ul> </li> </ul> <p></p>"},{"location":"project_documentation.html#github-pages-projects","title":"Github Pages-Projects","text":"<ul> <li>Go Back ESP-Series-&gt;WIFI Sniffer Project <ul> <li> DOC: https://jeonghunlee.github.io/wifisniffer/ </li> </ul> </li> </ul> <ul> <li>Go Back AI-&gt;AI-Agent with MCP Project <ul> <li> DOC: https://jeonghunlee.github.io/local-ai-agent-mcp/ </li> </ul> </li> </ul> <ul> <li>Go Back AI-&gt;AI-driven Embedded Continuous Testing <ul> <li> DOC: https://jeonghunlee.github.io/AI-driven-CI-CT/</li> <li> Pytest Results: https://jeonghunlee.github.io/AI-driven-CI-CT/tests/pytest/index.html</li> <li> Unittest Results: https://jeonghunlee.github.io/AI-driven-CI-CT/tests/unittest/index.html</li> </ul> </li> </ul> Technical Writing and Documentation Automation <p>Technical documents are maintained using MkDocs and Git-based version control.    Documentation and TEST reports are published through GitHub Pages as part of the project workflow.     </p> <p></p>"},{"location":"project_documentation.html#github-pages-myprofile","title":"GitHub Pages-MyProfile","text":"<ul> <li>Github Hosting Site Main and Repository (Current Git)<ul> <li> GIT: https://github.com/JeonghunLee/JeonghunLee.github.io</li> <li> WEB: https://jeonghunlee.github.io/ </li> </ul> </li> </ul> <p>Github Main Hosting Site and Repository</p> <p></p>"},{"location":"project_documentation.html#github-pages-test","title":"GitHub Pages TEST","text":"<p>various tests based on Github Pages (only for Test)    </p> <p>Github TEST Hosting Site and Repository</p> <p></p> <ul> <li>Github Pages based on Jeklly   <ul> <li> WEB: https://jeonghunlee.github.io/blog/</li> <li> GIT: https://github.com/JeonghunLee/blog</li> </ul> </li> </ul> <p></p> <ul> <li>Github Pages based on Jeklly <ul> <li> WEB: https://jeonghunlee.github.io/minima/</li> <li> GIT: https://github.com/JeonghunLee/minima/settings/pages</li> </ul> </li> </ul> <p></p> <ul> <li>Github Pages based on Jeklly <ul> <li> WEB: https://jeonghunlee.github.io/github-pages-with-jekyll/</li> <li> GIT: https://github.com/JeonghunLee/github-pages-with-jekyll</li> </ul> </li> </ul> <p></p>"},{"location":"project_esp_series.html","title":"ESP Series","text":"Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.     </p>"},{"location":"project_esp_series.html#technical-blog","title":"Technical Blog","text":"<ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Information Tags ESP32 MEM MCU-ESP32-MEM ESP32 RF MCU-ESP32-BT / MCU-ESP32-WIFI / RF-BT ESP32/ESP32-S3 ALL MCU-ESP32 / MCU-ESP32S3 WIFI-Sensing RF-WIFI-Sensing / RF-RTLS / RF-WIFI RF\u2013Radar / mmWave RF-Radar / RF-mmWave Sniffer Tool-Wireshark / NET-Packet Sniffer DevOps-Docs DevOps-Sphinx / DevOps-MkDocs / DevOps-ReadTheDocs USB IF-USB-CDC / IF-USB Security Security-SecureBoot / Security How to use these links <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.</p> ESP32 Memory Architecture and RTLS <p>This section explains the importance of the ESP32 memory system, focusing on the internal SRAM architecture, memory regions, and their impact on performance, stability, and real-time behavior.</p> FMCW Radar (TI-based Learning Background) <p>My understanding of FMCW radar systems is primarily based on Texas Instruments (TI) radar platforms and documentation,  including materials from TI Radar Academy and official TI technical resources.   </p> <p>Go Back Technical-Skills </p> <p></p>"},{"location":"project_esp_series.html#wifi-sniffer-esp32-s3","title":"WIFI Sniffer (ESP32-S3)","text":"<ul> <li> GIT: https://github.com/JeonghunLee/wifisniffer </li> <li>Supported Documentation:    <ul> <li>ReadTheDocs/GithubPages Hosting    </li> <li>Go To Documentation-&gt;ReadTheDocs-Project </li> <li>Go To Documentation-&gt;GithubPages-Project </li> </ul> </li> </ul> <p>Technical Summary</p> <ul> <li>Designed and implemented a WiFi packet sniffing tool based on ESP32-S3 with Wireshark integration</li> <li>Evaluated multiple documentation workflows:<ul> <li>MkDocs (Material) with Doxygen</li> <li>Sphinx with Doxygen (Breathe / Exhale)</li> <li>ReadTheDocs deployment pipeline</li> </ul> </li> <li>Verified USB CDC streaming reliability and real-time packet monitoring performance</li> </ul> <p> </p>"},{"location":"project_esp_series.html#esp-csi","title":"ESP-CSI","text":"<ul> <li>Purpose  Test WIFI CSI based on ESP32-S3 because of WIFI Sensing        </li> </ul> <ul> <li>TEST WIFI-CSI: <ul> <li> GIT: https://github.com/JeonghunLee/esp-csi</li> </ul> </li> </ul> <ul> <li>TEST WIFI-CSI RESULT: <ul> <li>https://github.com/JeonghunLee/esp-csi/blob/master/examples/esp-radar/console_test/SETUP_VSCODE.md </li> <li>https://github.com/JeonghunLee/esp-csi/blob/master/examples/get-started/csi_recv_router/SETUP_VSCODE.md </li> <li>https://github.com/JeonghunLee/esp-csi/blob/master/ESP32-S3_TEST.md </li> </ul> </li> </ul>"},{"location":"project_esp_series.html#wifi-sensing-array","title":"WIFI Sensing Array","text":"<ul> <li>Purpose  Research WiFi Sensing Array using ESP32 devices,  focusing on CSI-based spatial sensing and multi-device synchronization for indoor environment awareness.      have to compare with BLE Channel Sounding and FMCW Radar    </li> </ul> <ul> <li>Study WIFI Sensing Array:   <ul> <li> Main Web: https://espargos.net/ </li> <li> ESPargos Docs: https://espargos.net/docs/ </li> <li> GIT: https://github.com/JeonghunLee/pyespargos </li> </ul> </li> </ul> <ul> <li>Study TF Samples and 3D Point Cloud (Dataset)  <ul> <li> WEB: https://espargos.net/datasets/data/espargos-0005/</li> <li> WEB: https://espargos.net/datasets/data/espargos-0007/ </li> </ul> </li> </ul>"},{"location":"project_lorawan.html","title":"LoRA WAN","text":"Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.     </p>"},{"location":"project_lorawan.html#technical-blog","title":"Technical Blog","text":"<ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Information Tags Security Security-SecureBoot /  Security / NET-TLS How to use these links <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.</p> <p>Go Back Technical-Skills-&gt;Security </p> <p></p>"},{"location":"project_lorawan.html#lora-gateway","title":"LoRa Gateway","text":"<ul> <li>Purpose  LoRa Gateway(LoRaWAN) based on Semtech            Implement a Semtech SX1302/SX1303 based LoRaWAN gateway   Support packet forwarder and basic network server connectivity   </li> </ul> <ul> <li>Links:  <ul> <li> GIT: https://github.com/JeonghunLee/lora_gateway</li> <li> GIT: https://github.com/JeonghunLee/packet_forwarder</li> </ul> </li> </ul> <ul> <li>KCMVP: <ul> <li> WEB: https://www.keypair.co.kr/pages/secureic-kcmvp-en.html</li> </ul> </li> </ul> <p>Technical Summary</p> <p>Enhanced LoRaWAN stack with DTLS and KCMVP-based authentication &amp; encryption.</p> <p></p>"},{"location":"project_technical_skills.html","title":"Technial Skills","text":"<p>This page is a blog-centered technical skills index. Each category links to real-world implementation notes and deep-dive analyses  documented through my technical blog.    </p> <p>Use the Table of Contents (TOC) to quickly navigate each technical area.</p> <p></p> Quick access and Contact <p>Icon links to my platforms are available at the bottom of this page.      </p> <p>Technical Strengths</p> <ul> <li>Linux(Yocto) / RTOS-SRAM, DRAM / Bare-Metal BSP bring-up across TI, NXP, NVIDIA, Samsung, Broadcom, and other platforms.      </li> <li>Embedded firmware &amp; low-level SW/HW debugging and profiling </li> <li>DSP, RF Communication and Radar-related system(MCU/MPU) analysis across TI DSP/MCU, ESP32, STM32, Infineon, AVR, and other platforms</li> <li>AI/Edge AI applications for embedded systems and real-time edge processing   </li> <li>Embedded Security, Secure Boot, Secure Systems(TLS/DTLS, SELinux)</li> <li>DevOps, CI/CD, and Technical Documentation and professional IDEs and toolchains </li> <li>Extensive customer support experience across various customer platforms       </li> <li>Strong experience in mass production support, system stabilization, and field issue resolution    </li> </ul>"},{"location":"project_technical_skills.html#technical-blog","title":"Technical Blog","text":"<p>Senior Embedded Firmware Engineer focused on BSP bring-up and system debugging  across Linux, RTOS, and Android on TI, NXP, NVIDIA, and MPU-based platforms.    </p> <p></p> <ul> <li> My Technical Blog Tag-based Categories, only PC (not Mobile) </li> </ul> Various Experience and Deep Dive <p>Senior Embedded Firmware Engineer specialized in BSP development,  with strong expertise in RTOS, Linux Kernel, and Android system bring-up across diverse SoC platforms such as  TI (ARM + DSP), NXP i.MX, and other leading embedded/MPU architectures.   </p> Limited Tag Links and Public Content <p>Due to space limitations, not all technical details can be fully described here. Please refer to my technical blog for more detailed explanations.  </p> <p>How to use these links</p> <p>Click each Tag link to view all related posts at once. All links redirect to my technical blog (Blogger), organized using tag-based categories  The blog is primarily written in Korean, with English support available via Google Translate.     </p> <p></p>"},{"location":"project_technical_skills.html#bsp-main","title":"BSP-Main","text":"<p>Linux-based BSP bring-up and system integration across NVIDIA, TI, NXP, and ARM-based platforms.   </p> Information Tags NVIDIA Board EVM-Jetson AGX Xavier /  EVM-Jetson Nano / EVM-Jetson TX2 NVIDIA S/W NVIDIA-TensorRT /  NVIDIA-JetPack / NVIDIA-GPU / NVIDIA-TensorRT-Python NVIDIA DeepStream NVIDIA-DeepStream / NVIDIA-DeepStream SDK 3.0 / NVIDIA-DeepStream SDK 4.0 Gstream(DeepStream) Multimedia-Gstreamer TI Board SOC-DM368 /  SoC-DM81xx TI Board SoC-Sitara / SoC-OMAP NXP Board SoC-IMX6 / SoC-IMX6-UUU / SoC-IMX8 Samsung Board EVM-ODROID-X2 Raspberry Pi Board EVM-RaspberryPi3-B <p></p> About OMAP Experience and NDA Constraints <p>Although I have in-depth practical experience with TI OMAP-based systems,  through work as a TI 3<sup>rd</sup>-party developer and technical consultant, the level of detail publicly documented here is intentionally limited.  </p> Personally Owned and Tested Boards <p>In addition to boards used in professional projects,(e.g., Odroid, Raspberry Pi, NXP(IMX6), TI(Sitara)),  a significant number of the platforms listed above were personally purchased and tested for independent study and experimentation.  </p> <p></p>"},{"location":"project_technical_skills.html#bsp-bringup","title":"BSP-BringUp","text":"<p>System-level BSP bring-up covering U-Boot, DRAM tuning, and Linux kernel optimization.  </p> System Bring-up Tags U-Boot Uboot / Uboot-Script DRAM Opt-DRAM / RAM-DRAM Kernel Optimization Tags Linux \u2013 Kernel / Module Linux-Kernel / Linux-Module Linux \u2013 Device Tree Linux-DeviceTree Linux \u2013 Proc/sys Linux-sys/udev / Linux-proc Linux \u2013 BootTime Linux-BootTime Linux \u2013 Service (Init/ Cron) Linux-init/systemd / Linux-cron Linux \u2013 MTD and Filesystem Linux-MTD Linux \u2013 Network Linux-iptables <p>Silicon Bring-up and System Setup</p> <p>Topics include DRAM PHY tuning, memory performance optimization, system boot-time improvement, and early-stage boot debugging.</p> <p></p> Tools and DevelEnv Tags DevelEnv / Package DevelEnv / Ubuntu x86 DevelEnv / Ubuntu x86 Package Tips For Linux Tips For Linux Tools For Wins Tools For Wins Tool-Virtual Box and WSL Tool-Virtual Box / Window-WSL Tool-Wireshark Tool-Wireshark Tool-Linux Linux-Tools <p>Development Environment &amp; System-Level Tooling</p> <p>This section covers practical development environments and tools  for embedded and system-level software development.  It includes Linux-based workflows, Ubuntu x86 setups, and debugging utilities. </p> <p></p>"},{"location":"project_technical_skills.html#bsp-devicedrivers","title":"BSP-DeviceDrivers","text":"<p>System-level device driver development across USB, MIPI, PCIe, Ethernet, storage, and control buses</p> Information Tags IF \u2013 USB ALL IF-USB IF \u2013 USB CDC IF-USB-CDC / IF-USB-ACM / IF-USB-LTE IF \u2013 USB Device IF-USB-DEVICE / IF-USB-Descriptor / IF-USB-libusb IF \u2013 MIPI IF-MIPI / IF-MIPI-DSI / IF-MIPI-CSI IF \u2013 HDMI IF-HDMI IF \u2013 PCIe / UCIe / PHY IF-PCIe / IF-UCIe / IF-PHY / IF-CXL IF \u2013 ETH / MII IF-ETH / IF-MII IF \u2013 RS485 / RS485-OTA / MODBUS IF-RS485 / IF-RS485-OTA / IF-MODBUS IF \u2013 LTE / GPS IF-LTE / IF-GPS IF \u2013 Control Bus IF-I2C / IF-SPI / IF-PWM IF \u2013 Storage / Boot IF-NAND / IF-MMC / IF-SDCard / IF-UEFI IF \u2013 PLL IF-PLL <p>Device Driver Development and Optimization</p> <p>This section covers the development and optimization of various device drivers   across multiple hardware interfaces, focusing on stability, performance tuning,   and system-level integration.   </p> <p> </p>"},{"location":"project_technical_skills.html#bsp-debug","title":"BSP-Debug","text":"<p>System-level debugging and profiling across user space, kernel, and hardware layers.  </p> SW Debug and Profile Tags Debug \u2013 GDB / Binutils Debug-GDB / Debug-Binutils Debug \u2013 Kernel Debug-Kernel Debug \u2013 BootChart Debug-BootChart Debug \u2013 Log / Trace Debug-Log / Debug-Trace Debug \u2013 Network / USB Debug-Network / Debug-USB Debug \u2013 Memory / Profile Debug-Memory / Debug-Profile Debug \u2013 General / Analysis Debug-Info HW Debug and Profile Tags HW Tools(Scope/Analyzer) Tools For HW HW JTAG/SWD, OpenOCD JTAG/SWD / OpenOCD Debugging and Profiling Techniques <p>This section introduces various debugging and profiling techniques  used across different system layers, including user space, kernel space, and hardware-level analysis. </p> <p></p>"},{"location":"project_technical_skills.html#bsp-sram-and-dram","title":"BSP-SRAM and DRAM","text":"<p>System-level analysis of ESP32 SRAM architecture and FreeRTOS behavior.   </p> ESP32 Memory/OS Tags ESP32 MEM MCU-ESP32-MEM FreeRTOS FreeRTOS <p>ESP32 Memory &amp; RTOS Behavior</p> <p>Covers ESP32 internal SRAM architecture and FreeRTOS behavior,  focusing on performance, stability, and real-time constraints in practical embedded systems.  </p> <p></p> <p>System-level analysis of DRAM optimization, bank interleaving, and timing calibration .</p> System Bring-up Tags DRAM Opt-DRAM / RAM-DRAM DRAM DRAM Timing Calibration A DRAM DRAM Timing Calibration B DRAM DRAM Bank Interleaving DRAM DRAM Topology and Latency <p>DRAM Optimization, Bank Interleaving &amp; Timing Calibration</p> <p>Covers DRAM performance optimization, bank interleaving, and DRAM timing calibration,  focusing on memory bandwidth, access latency, signal stability,     and reliable high-speed data transfer in practical embedded systems.   </p> <p></p>"},{"location":"project_technical_skills.html#bsp-yocto","title":"BSP-Yocto","text":"<p>System-level BSP build analysis with Yocto Project.   </p> Information Tags Yocto ALL Yocto  Yocto \u2013 Basics / Layer Yocto-Basic / Yocto-Layer  Yocto \u2013 Recipe / User Configuration Yocto-Recipe / Yocto-UserConf Yocto \u2013 Profile / Partition Yocto-Profile / Yocto-Partition <p>Yocto (BSP) and Recipe / Layer</p> <p>This section organizes my Yocto-related notes by topic,  covering core concepts, layer management , BitBake recipes, user configuration, image partitioning, and build optimization. </p> <p></p> <p></p>"},{"location":"project_technical_skills.html#ide-tools","title":"IDE Tools","text":"<p>System-level IDE workflows covering build, trace, profiling, and hardware-assisted debugging.   </p> IDE-General Tags IDE \u2013 Eclipse CDT IDE-Eclipse-CDT IDE \u2013 Trace Compass IDE-Trace Compass IDE-TI Tags IDE \u2013 CCS v3 / CCS v6 IDE-CCSv3 / IDE-CCSv6 IDE \u2013 CCS / Eclipse IDE-CCS / IDE-Eclipse IDE-NVIDIA Tags IDE \u2013 Nsight IDE-Nsight IDE-Keil/ST Tags IDE \u2013 uVision IDE-uVision IDE \u2013 STM32CubeMX IDE-STM32CubeMX IDE-MS Tags IDE \u2013 Visual Studio IDE-VS IDE \u2013 VS Code IDE-VS Code <p>Various IDEs and Deep Dive with H/W Debugging</p> <p>This section organizes my IDE-related notes across multiple development environments, including CCS(TI), Eclipse, VS Code, Nsight(NVIDIA), uVision(Keil), and STM32CubeMX(ST).  The focus is on practical usage, debugging workflows, trace and profiling tools, and hardware-level debugging techniques used in real embedded system development. </p> <p></p> <p></p>"},{"location":"project_technical_skills.html#security","title":"Security","text":"<p>System-level security integration across Secure Boot, TLS/DTLS, certificates, Wi-Fi authentication. </p> Information Tags Security ALL OpenSSL / Security / NET-TLS SecureBoot Security-SecureBoot Certificate Security-Certificate Security Android / SELinux Security-Android /Linux-SELinux <p>Security and Cryptography Scope</p> <p>Covers fundamental cryptographic concepts and their extensions, including TLS/DTLS.  Also includes practical understanding of WiFi security mechanisms such as EAP-based authentication. Focused on system-level integration rather than standalone cryptographic algorithms. </p> <p></p> <p></p>"},{"location":"project_technical_skills.html#android","title":"Android","text":"<p>System-level Android AOSP exploration using the PDK environment, focused on build and system integration.  </p> Information Tags Android \u2013 AOSP App / Build Android-AOSP-App / Android-AOSP-Build Android \u2013 AOSP Info / Partition Android-AOSP-Info / Android-AOSP-Patition Android \u2013 AOSP USB / WiFi Android-AOSP-USB-Gadget / Android-AOSP-WIFI Android \u2013 SDK / SDK Tools Android-SDK / Android-SDK-Tools Android \u2013 JDK / SCM Android-JDK / Android-SCM Android \u2013 SELinux / PDK (PWM) Android-SELinux / Android-PDK-PWM <p>Android AOSP (Personal / PDK-Based Exploration)</p> <p>The Android AOSP work listed here (e.g., Odroid-based platforms)  was conducted as a personal technical exploration, primarily using the Android PDK environment rather than for commercial product development.  </p> <p></p> <p></p>"},{"location":"project_technical_skills.html#rf-communication-radar","title":"RF Communication &amp; Radar","text":"<p>System-level analysis of RF communication and Radar behavior/RTLS across Wi-Fi, Bluetooth, and cellular (4G/5G) systems.   </p> RF-General Tags RF \u2013 ALL RF-INFO RF \u2013 WiFi RF-WIFI / MCU-ESP32-WIFI RF \u2013 Bluetooth RF-BT /MCU-ESP32-BT / RF-BT-TOOLS RF \u2013 Cellular / V2X RF-LTE / RF-5G / RF-DSRC ESP32 Series Tags ESP32/ESP32-S3 ALL MCU-ESP32 / MCU-ESP32S3 <p>RF Wi-Fi / Bluetooth / 4G/5G</p> <p>Covers practical RF fundamentals and system-level behavior across Wi-Fi, Bluetooth, and cellular (4G/LTE) technologies.</p> <p></p>"},{"location":"project_technical_skills.html#rf-radar","title":"RF Radar","text":"Radar Tags RF \u2013 Radar ALL RF-Radar RF \u2013 TI 4D FMCW TI 4D FMCW RF Radar vs RF Communication RF Radar vs RF Comm. RF \u2013 WiFi Sensing / RTLS (BLE CS) RF-WIFI-Sensing / RF-RTLS <p>FMCW Radar (TI-based Learning Background)</p> <p>My understanding of FMCW radar systems is primarily based on Texas Instruments (TI) radar platforms and documentation,  including materials from TI Radar Academy and official TI technical resources.   </p> <p></p>"},{"location":"project_technical_skills.html#rf-rtls","title":"RF RTLS","text":"RTLS Tags RF \u2013 WiFi Sensing / RTLS (BLE CS) RF-WIFI-Sensing / RF-RTLS RF \u2013 TI BLE Channel Sounding BLE-RTLS RF \u2013 Nordic BLE Channel Sounding BLE-RTLS <p>RTLS (WiFi Sensing, BLE Channel Sounding)</p> <p>Covers Wi-Fi CSI\u2013based sensing and BLE Channel Sounding (AoA/AoD) concepts for RTLS, ranging, and presence/motion detection applications.</p> <p></p>"},{"location":"project_technical_skills.html#rf-dsp","title":"RF DSP","text":"DSP Tags RF Mixer (I/Q Mixer) RF-Mixer PHY based on DSP PHY based on DSP <p>RF &amp; PHY from a DSP Perspective</p> <p>Explores RF Mixer (I/Q Mixer) and PHY-layer processing from a DSP-centric perspective, focusing on the signal-processing concepts and implementation principles behind RF and communication systems.</p> <p></p>"},{"location":"project_technical_skills.html#devops-cicdct","title":"DevOps-CI/CD/CT","text":"<p>System-level DevOps workflows covering CI/CD, containerization, and technical documentation.  </p> Information Tags DevOps \u2013 CI/CD / Docker DevOps-CI/CD / DevOps-Docker DevOps \u2013 Documentation (Sphinx / Doxygen) DevOps-Sphinx / DevOps-Doxygen DevOps \u2013 Docs Site (MkDocs / ReadTheDocs) DevOps-Mkdocs / DevOps-ReadTheDoc DevOps \u2013 UML / ITS DevOps-UML DevOps \u2013 General DevOps DevOps \u2013 CI/CD/CT Automation Github Local Host Automation <p>DevOps &amp; Documentation Workflow</p> <p>This section covers DevOps practices for embedded and system-level projects, including CI/CD, containerization, and technical documentation workflows.</p> <p></p>"},{"location":"project_technical_skills.html#devops-source-control","title":"DevOps-Source Control","text":"Information Tags DevOps \u2013  ITS DevOps-ITS SCM \u2013 Git / GitHub SCM-GIT / SCM-GITHUB SCM \u2013 Gerrit / Repo SCM-Gerrit / SCM-Repo SCM \u2013 SVN SCM-SVN <p>Source Code Management (SCM) and ITS(Issue Tracking System)</p> <p>This section covers source code management systems used in software development, including Git-based workflows, code review systems, and legacy SCM tools.</p> <p> </p>"},{"location":"project_technical_skills.html#ai-edge-ai","title":"AI (Edge AI)","text":"<p>System-level exploration of AI and TinyML(Edge AI) for edge and embedded applications.  </p> Information Tags AI \u2013 Data / Dataset AI-Bigdata / AI-DataSet AI \u2013 Annotation / Preprocessing AI-Annotation Tools / AI-OCR AI \u2013 Machine / Deep Learning AI-Machine/Deep Learning / AI-Tensorflow AI \u2013 Transfer Learning / Object Detection AI-Transfer Learning / AI-Object Detection AI \u2013 Edge / TinyML AI-Edge / AI-TinyML AI \u2013 Colab / Applied AI AI-Colab / AI-OpenALPR <p>Learning Background (TinyML / Edge AI)</p> <p>My learning in TinyML and Edge AI has been primarily based on   technical materials from NVIDIA, along with knowledge shared through  TinyML (Edge AI) and Data Science meetups.  </p> <p> </p>"}]}